package servicio;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import java.util.Map;import org.junit.jupiter.api.Test;import config.ConfiguracionMercadoPago;import pagos.PasarelaPagoOnline;
class CapacidadesPagoConfiguradasTest {@Test void onlineSoloSePublicaTrasPreflight(){var apagadaCfg=ConfiguracionMercadoPago.desde(Map.of("MP_ENABLED","false"));var apagada=new CapacidadesPagoService(apagadaCfg,mock(PasarelaPagoOnline.class)).obtener();assertFalse(apagada.pagoOnlineDisponible());var activaCfg=ConfiguracionMercadoPago.desde(Map.of("MP_ENABLED","true","MP_ACCESS_TOKEN","APP_USR-test","MP_WEBHOOK_SECRET","y","MP_PUBLIC_BASE_URL","https://club.example","MP_TEST_USER_ID","123"));PasarelaPagoOnline p=mock(PasarelaPagoOnline.class);when(p.disponible()).thenReturn(true);var activa=new CapacidadesPagoService(activaCfg,p).obtener();assertTrue(activa.pagoOnlineDisponible());assertEquals("MERCADO_PAGO",activa.proveedorOnline());}}
